<template><span v-if="valid" class="certified-honor-badge" :class="['place-' + artwork, {compact}]" :data-certified-honor="artwork"><span class="certified-honor-light" aria-hidden="true"/><img v-if="source && !failed" :src="source" alt="" draggable="false" @dragstart.prevent @error="failed=true"/><span class="certified-honor-copy"><strong>{{ title }}</strong><small><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M8 1.5 13 3v4.2c0 3-2.4 5.1-5 6.7-2.6-1.6-5-3.7-5-6.7V3z"/><path d="m5.2 7.5 1.9 1.9 3.6-3.7"/></svg>已认证 · {{ year }}</small></span></span></template>
<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {worldHonorArtwork,worldHonorBadgePath,validHonorYear} from '@/utils/honorPresentation';
// Verification and the exact title come from the honor service; artwork never grants an award.
const props=defineProps<{title?:string;placement?:string;verified:boolean;year?:number;compact?:boolean}>();
const artwork=computed(()=>worldHonorArtwork(props.placement)),source=computed(()=>worldHonorBadgePath(props.placement));
const valid=computed(()=>props.verified===true&&!!props.title?.trim()&&validHonorYear(props.year)&&!!artwork.value);
const failed=ref(false);watch(source,()=>{failed.value=false;});
</script>
